import utilSrv from "../base/utils"
export default (function(){
    function injectStyles(el) {
        const style = document.createElement('style');
        style.id = 'x-scraper-style';
        style.textContent = `
            img.xs-img-selected {
                outline: 3px solid #939393 !important;
                outline-offset: 2px !important;
                box-shadow: 0 0 15px #c3c3c3 !important;
                border-radius: 4px !important;
                transform: scale(0.75) !important;
                transition: all 0.2s ease !important;
                cursor: pointer !important;
                z-index: 9999 !important;
                position: relative !important;
            }
            
            img.xs-img-active {
                outline: 5px solid #ff4757 !important;
                outline-offset: 4px !important;
                box-shadow: 0 0 30px rgba(226, 33, 49, 0.8) !important;
                transform: scale(0.85) !important;
            }
            
            img.xs-img-selected:hover {
                outline-color: #ff4757 !important;
                box-shadow: 0 0 25px rgba(255, 71, 87, 0.6) !important;
            }

            /* 视频基础高亮 */
            video.xs-video-selected,
            .xs-video-wrapper.xs-video-selected {
                outline: 4px solid #939393 !important;
                outline-offset: 2px !important;
                box-shadow: 0 0 20px #c3c3c3 !important;
                border-radius: 6px !important;
                transition: all 0.2s ease !important;
                cursor: pointer !important;
                position: relative !important;
                transform: scale(0.85) !important;
                z-index: 9999 !important;
            }
            
            video.xs-video-active,
            .xs-video-wrapper.xs-video-active {
                outline-color: #ff4757 !important;
                box-shadow: 0 0 30px rgba(226, 33, 49, 0.8) !important;
                transform: scale(0.95) !important;
            }
            
            video.xs-video-selected:hover,
            .xs-video-wrapper.xs-video-selected:hover {
                outline-color: #ff4757 !important;
                box-shadow: 0 0 25px rgba(255, 71, 87, 0.6) !important;
            }
        `;
        el.appendChild(style);
    }
    
    function highlightAllImages() {
        const events = ['mouseenter', 'mouseover', 'mouseout', 'mouseleave',
            'mousemove', 'mousedown', 'mouseup'];
        events.forEach(eventName => {
            document.removeEventListener(eventName, preventMouseEvent, true);
            document.addEventListener(eventName, preventMouseEvent, true);
        });
        document.removeEventListener('click', handleClick, true);
        document.addEventListener('click', handleClick, true);
        document.querySelectorAll('img').forEach(img => {
            img.classList.add('xs-img-selected');
        });
        //处理iframe包裹的情况逻辑
        document.querySelectorAll('iframe').forEach(iframe => {
            try {
                const doc = iframe.contentDocument || iframe.contentWindow.document;
                doc.removeEventListener('click', handleClick, true);
                doc.addEventListener('click', handleClick, true);
                doc.querySelectorAll('img').forEach(img => {
                    img.classList.add('xs-img-selected');
                });
            } catch (err) {
                utilSrv.Write(utilSrv.DEBUG, '跨域 iframe，跳过', err);
            }
        });
        utilSrv.Write(utilSrv.INFO, '已高亮图片，共',
             document.querySelectorAll('.xs-img-selected').length, '张');
    }

    function highlightAllVideos() {
        const videos = [];
        const events = ['mouseenter', 'mouseover', 'mouseout', 'mouseleave',
            'mousemove', 'mousedown', 'mouseup'];
        events.forEach(eventName => {
            document.removeEventListener(eventName, preventMouseEvent, true);
            document.addEventListener(eventName, preventMouseEvent, true);
        });
        document.removeEventListener('click', handleClick, true);
        document.addEventListener('click', handleClick, true);
        document.querySelectorAll('video').forEach(v => {
            videos.push({ el: v, type: 'video' });
        });
        videos.forEach(({ el, type }) => {
            (!el.classList) && (el.classList = []);
            if (el.classList.contains('xs-video-selected')) return;
            if (type === 'video') {
                el.classList.add('xs-video-selected');
            } else {
                el.classList.add('xs-video-wrapper', 'xs-video-selected');
            }
        });
        utilSrv.Write(utilSrv.INFO, '已高亮视频，共', videos.length, '个');
    }
    
    
    function updateIndexes() {
        document.querySelectorAll('.xs-video-active').forEach((el, index) => {
            el.setAttribute('data-xs-index', index + 1);
        });
    }

    function preventMouseEvent(e) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
    }

    function handleClick(e) {
        let tag = e.target;
        (!tag.classList) && (tag.classList = []);
        if (tag.tagName === 'IMG' && tag.src && tag.src.startsWith('http')) {//图片的情况
            if (!tag.classList.contains('xs-img-selected')) return;
            e.preventDefault();
            e.stopPropagation();
            tag.classList.toggle('xs-img-active');
            utilSrv.Write(utilSrv.INFO, "当前选中图片", 
                document.querySelectorAll('.xs-img-active').length, '张');
            return
        }
        if (tag.tagName === 'VIDEO') {
           // 只处理已高亮的视频
            if (!tag.classList.contains('xs-video-selected')) return;
            e.preventDefault();
            e.stopPropagation();
            if (tag.classList.contains('xs-video-active')) {
                tag.classList.remove('xs-video-active');
                tag.removeAttribute('data-xs-index');
                updateIndexes();
            } else {
                tag.classList.add('xs-video-active');
                const index = document.querySelectorAll('.xs-video-active').length;
                tag.setAttribute('data-xs-index', index);
            }
        }
        utilSrv.Write(utilSrv.INFO, "当前选中视频", 
            document.querySelectorAll('.xs-video-active').length, '个');
    }
    
    function init() {
        injectStyles(document.head);
    }
    
    return {
        init,
        highlightAllImages: highlightAllImages,
        highlightAllVideos: highlightAllVideos,
        getSelectedImages: () => {
            return Array.from(document.querySelectorAll('img.xs-img-active'));
        },
        getSelectedVideos: () => {
            return Array.from(document.querySelectorAll('.xs-video-active')).map(el => {
                if (el.tagName === 'VIDEO') {
                    return {
                        type: 'video',
                        src: el.src || el.currentSrc,
                        poster: el.poster || '',
                        duration: el.duration,
                        width: el.videoWidth,
                        height: el.videoHeight
                    };
                } else {
                    // 容器类型（iframe 或 div）
                    const iframe = el.querySelector('iframe');
                    return {
                        type: 'container',
                        tagName: el.tagName,
                        src: iframe ? iframe.src : '',
                        className: el.className
                    };
                }
            });
        },
        clear: () => {
            document.removeEventListener('click', handleClick, true);
            document.querySelectorAll('img').forEach(img => {
                img.classList.remove('xs-img-selected', 'xs-img-active');
            });
            document.querySelectorAll('.xs-video-selected, .xs-video-active').forEach(el => {
                el.classList.remove('xs-video-selected', 'xs-video-active', 'xs-video-wrapper');
                el.removeAttribute('data-xs-index');
            });
        }
    };
})();