require("@/s/wasm_exec");
import utilSrv from "../base/utils";
import { Interpreter } from "@/static/lib/eval5.min";
export default (function(){
    var contentApp = {};//content-script APP
    //插入监听的js代码 通过全局直接导入即可
    contentApp.InjectSnifferJs = () => {
        let src = chrome.runtime.getURL('static/sniffer.min.js');
        contentApp.appendJsScript(src);
    };

    //加载js文件的逻辑
    contentApp.appendJsScript = (src, cb=null) => {
        let s = document.createElement('script');
        s.src = src;
        s.onload = function () {
            cb && cb(); //加载完成执行
            if (process.env.NODE_ENV != 'development') {//开发调试使用
                this.remove();
            }
        };
        (document.head || document.documentElement).appendChild(s);
    };

    //通过插入dom执行
    contentApp.RunScriptDom = (script='')=>{
        let uuidStr = utilSrv.uuid();
        let s = document.createElement('script');
        s.text = 'window.'+uuidStr+'='+script; //设置执行脚本
        (document.head || document.documentElement).appendChild(s);
    };

    //通过插入dom执行
    contentApp.RunScriptCtx = (script='', isThrow=false)=>{
        try {
            const interpreter = new Interpreter(window, {
                timeout: 1000,
            });
            let result = interpreter.evaluate(script);
            return result
        } catch (err) {//出错处理逻辑
            (err && err.message) && (err = err.message);
            utilSrv.Write(utilSrv.ERROR, "脚本执行异常", err);
            if (isThrow) {//编辑器执行需要把异常抛给调用方
                throw err;
            }
        }
    };

    //检查是否支持wasm
    const isWasmAvailable = async () => {
        try {
            // 测试WASM是否可用
            const wasmCode = new Uint8Array([0,97,115,109,1,0,0,0]);
            await WebAssembly.instantiate(wasmCode);
            return true;
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "WASM不可用", err);
            return false;
        }
    }

    //加载wasm解析器
    const loadWasmResource = async ()=>{
        try {
            const url = chrome.runtime.getURL("/s/scraper.wasm.gz");
            const resp = await fetch(url);
            const compressed = new Uint8Array(await resp.arrayBuffer());
            const ds = new DecompressionStream('gzip'); // ✅ 这里用 gzip
            const stream = new Blob([compressed]).stream().pipeThrough(ds);
            const response = new Response(stream);
            const decompressed = new Uint8Array(await response.arrayBuffer());

            const go = new Go();// ✅ 记得运行
            const result = await WebAssembly.instantiate(decompressed, go.importObject);
            go.run(result.instance); 
            console.log('wasm 加载成功');
            return result.instance;
        } catch (errS) {
            utilSrv.Write(utilSrv.ERROR, "加载wasm失败", errS);
        }
    };

    //加载采集器的逻辑
    contentApp.wasmScraper = async()=> {
        try {
            const isWasm = await isWasmAvailable();
            if (!isWasm) {//是否支持wasm的情况
                return
            }
            await loadWasmResource();//加载wasm资源
        } catch (err) {
            utilSrv.Write(utilSrv.ERROR, "加载wasm异常", err);
        }
    };
    return contentApp;
})();