import utilSrv from "./js/base/utils"
import customSrv from "./js/ct_script/custom"
import contentApp from "./js/ct_script/script"
import highlightSrv from "./js/ct_script/highlight"
import { contentFFmpeg } from "./js/base/cb-ffmpeg"
import { captureFullPage, downloadImages,
    downloadVideo} from "./js/ct_script/media"

(function(){
    if (typeof window === 'undefined') {
        return;//非window环境的情况
    }
    const docType = document.contentType || '';
    if (docType !== 'text/html' && docType !== 'application/xhtml+xml') {
        return;
    }
    const path = window.location.pathname.toLowerCase();
    if (utilSrv.isResourceSkip(path)) {
        return;
    }
    if (window.__contentScriptInited) {
        return;
    }
    window.__contentScriptInited = true;
    utilSrv.Write(utilSrv.INFO, "content script start",
        process.env.NODE_ENV, chrome, window);
    
    const doListener = ()=>{//启动消息监听
        if (window === window.top) {//顶级窗口才执行
            const cFFmpeg = contentFFmpeg(); //初始化
            //同步返回false/异步的返回true
            utilSrv.Write(utilSrv.INFO, '注册CG监听');
            chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
                utilSrv.Write(utilSrv.INFO, 'CG', message);
                if (message.type && message.type == utilSrv.msgTypeRunScript) {
                    if(message.run_ctx && message.run_ctx === "content_script") {//通过内部逻辑执行
                        contentApp.RunScriptCtx(message.script);//运行脚本
                    } else {
                        contentApp.RunScriptDom(message.script);//运行脚本
                    }
                    sendResponse("OK");
                    return false;
                } else if (message.type && message.type == utilSrv.msgTypeCaptureFull) {
                    captureFullPage().then(()=>{
                        sendResponse({code:0});
                    }).catch((err)=>{
                        sendResponse({code:500, error: err});
                    });
                    return true;
                } else if (message.type && message.type == utilSrv.msgTypeWasmScraper) {
                    window.xScraper.domUtil.WebScraper(message.data).then((res)=>{
                        sendResponse({code:0, result: res});
                    }).catch((err)=>{
                        sendResponse({code:500, error: err});
                    });
                    return true;
                } else if (message.type && message.type == utilSrv.msgTypeSelectedImages) {
                    highlightSrv.highlightAllImages();
                    sendResponse({code:0});
                    return false;
                } else if (message.type && message.type == utilSrv.msgTypeSelectedVideos) {
                    highlightSrv.highlightAllVideos();
                    sendResponse({code:0});
                    return false;
                } else if (message.type && message.type == utilSrv.msgTypeSelectedClear) {
                    highlightSrv.clear(); //取消选中的逻辑
                    sendResponse({code:0});
                    return false;
                } else if (message.type && message.type == utilSrv.msgTypeDownloadImages) {
                    downloadImages().then((nImages)=>{
                        sendResponse({code:0, n:nImages});
                    }).catch((err)=>{
                        sendResponse({code:500, error: err});
                    });
                    return true;
                } else if (message.type && message.type == utilSrv.msgTypeDownloadVideos) {
                    downloadVideo().then((nVideos)=>{
                        sendResponse({code:0, n:nVideos});
                    }).catch((err)=>{
                        sendResponse({code:500, error: err});
                    });
                    return true;
                } else if (message.type && message.type == utilSrv.msgTypeFFmpegDownload) {
                    cFFmpeg.init(message.data).then(()=>{
                        sendResponse({code:0});
                    }); //通知bg建立好消息管道，准备启动下载
                    return true
                } else {
                    return false;
                }
            });
        }
    }
    try {
        (async()=>{
            let sKey = await utilSrv.Sdomain(window.location.href);
            const data = await chrome.storage.local.get(sKey);
            if (data[sKey] && data[sKey].n === 1) {
                contentApp.InjectSnifferJs()//导入监听
            }
            if (data[sKey] && data[sKey].m === 1) {
                doListener();//导入监听
            }
            if (data[sKey] && data[sKey].w === 1) {
                contentApp.wasmScraper(); //采集加载
            }
            highlightSrv.init();
            setTimeout(()=>{//提取执行提交
                customSrv.runScript();
            }, 100);
        })();
    } catch (err) {//失败的情况
        utilSrv.Write(utilSrv.INFO, "inject error", err);
    }
})()