import utilSrv from "../base/utils"
import highlightSrv from "./highlight"
import messageSrv from "../base/m-sender"
import html2canvas from '@/static/lib/html2canvas-pro.min'

//下载文件的情况
export const downloadFile =(dataUrl, filename) => {
    const a = document.createElement('a');
    a.href = dataUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(dataUrl), 10000);
}

// 截取整个 body
export const captureFullPage = async () => {
    let scale = 0.9, foreignObjectRendering = false;
    let width = Math.max(1, document.documentElement.scrollWidth || window.innerWidth);
    let height = Math.max(1, document.documentElement.scrollHeight || window.innerHeight);
    if (height > 20480) {//限制一下高度
        scale  = 0.5;
        foreignObjectRendering = true;
    } else if (height > 8182) {
        scale = 0.7;
        foreignObjectRendering = true;
    } else if (height > 4096) {
        scale = 0.8;
    }
    const canvas = await html2canvas(document.body, {
        scale: scale,              // 提高清晰度
        useCORS: true,           // 允许跨域图片
        allowTaint: false,
        logging: false,
        width: width,
        height: height,
        foreignObjectRendering: foreignObjectRendering  // 加这一行
    });
    const dataUrl = canvas.toDataURL('image/png');
    downloadFile(dataUrl, '截图_网页全屏-'+utilSrv.DateStr(0, 'YmdHis'));
}

// 图片下载的业务处理逻辑
export const downloadImages = async() => {
    let nImages = 0;
    const data = {url:window.location.href, status:1, ref_type:1, items:[]};
    const images = highlightSrv.getSelectedImages();
    for (let i = 0; i < images.length; i++) {
        try {
            const res = await fetch(images[i].src, { mode: 'cors' });
            const blob = await res.blob();
            const dataUrl = URL.createObjectURL(blob);
            downloadFile(dataUrl, '图片-'+utilSrv.DateStr(0, 'YmdHis')+'-'+String(i+1));
            nImages++;
            data.items.push({src:images[i].src}); //记录下载历史
        } catch (error) {
            utilSrv.Write(utilSrv.INFO, "图片下载失败", err);
        }
    }
    const state = await messageSrv.doSendMessage({type:utilSrv.msgTypeInsertMedia, data:data});
    if (state) {
        utilSrv.Write(utilSrv.INFO, "图片记录保存状态", state);
    }
    return nImages;                    
}

// 视频下载的业务处理逻辑
export const downloadVideo = async() => {
    let nVideos = 0;
    const videos = highlightSrv.getSelectedVideos();
    for (let i = 0; i < videos.length; i++) {
        try {
            const res = await fetch(videos[i].src, { mode: 'cors' });
            const blob = await res.blob();
            const dataUrl = URL.createObjectURL(blob);
            downloadFile(dataUrl, '视频-'+utilSrv.DateStr(0, 'YmdHis')+'-'+String(i+1));
            nVideos++;
        } catch (err) {
            utilSrv.Write(utilSrv.INFO, "视频下载失败", err);
        }
    }
    return nVideos;             
}