import utilSrv from "../base/utils"
import hookSrv from "../base/hooks"
import apiCore from "../base/apicore"
import domUtil from "../base/domutil"
import messageSrv from "../base/m-sender"
import contentApp from "./script"
export default (function(){
    //网络监听回调
    messageSrv.pageMessageListener();
    //提取任务并执行任务的逻辑
    const runScript = async() => {
        const link = window.location.href;
        messageSrv.doSendTaskDispatchMessage(link, async(task)=>{
            utilSrv.Write(utilSrv.INFO, "请求bgScript获取任务...", task);
            try {
                if (task) {//任务处理
                    execTask(task); //请求到任务执行
                    let sKey = await utilSrv.Sdomain(window.location.href);
                    const data = await chrome.storage.local.get(sKey);
                    if (!data || !data[sKey]) {//初始化的情况
                        chrome.storage.local.set({[sKey]: { n: 1, m: 1 }});
                    }
                }
            } catch(errS) {
                utilSrv.Write(utilSrv.ERROR, "脚本执行异常", errS);
            }
        });
    };
    //执行任务处理逻辑
    const execTask = async(task={}) => {
        if (!task || (!task.script && !task.script_uuid)) {
            return;//数据为空的情况
        }
        if (!task.script) {//脚本为空的情况
            const param  = {type:utilSrv.msgTypeGetScript,
                uuid: task.script_uuid, from:task.from || 'x.script'};
            const script = await messageSrv.doSendMessage(param);
            if (!script) {//提取执行脚本异常的情况
                utilSrv.Write(utilSrv.INFO, "工具到期释放...", task);
                return;
            }
            task.script = script; //获取执行脚本
        }
        utilSrv.Write(utilSrv.INFO, "启动执行任务...", task);
        hookSrv.ScriptHookReset();//任务重置
        //检测dom是否加载完成，当前无法通过监听完成此动作
        const tickDomInterval = window.setInterval(()=>{
            if (document.readyState == "complete") {
                window.clearInterval(tickDomInterval);
                hookSrv.RunHooks(hookSrv.onDomLoaded, task);
            }
        },1000);
        /*//网络监听逻辑，根据地址匹配回调
        const tabId = (task && task.tabId)? task.tabId:-1;
        if (tabId > 0) {//注册一个消息回调函数
            utilSrv.Notify = (data={})=>{
                messageSrv.doSendTabMessage(tabId, data);
            }
        }*/
       //网络监听逻辑，根据地址匹配回调
        messageSrv.sNetworkHooks((url, data)=>{
            const hooks = hookSrv.MatchNetSniffer(url);
            hookSrv.RunHooks(hooks, task, data, url);
        });
        utilSrv.Write(utilSrv.INFO, 'start run script:', task);
        window.xScraper = {utilSrv:utilSrv, apiCore:apiCore,
            hookSrv:hookSrv, domUtil:domUtil};
        if(task.run_ctx && task.run_ctx === "content_script") {//通过内部逻辑执行
            contentApp.RunScriptCtx(task.script);//运行脚本
        } else {
            contentApp.RunScriptDom(task.script);//运行脚本
        }
        hookSrv.RunHooks(hookSrv.onStart, task); //启动服务的任务hooks
    };
    return {runScript};
})();